insert into public.permission_definitions(permission_key,label,category,sort_order) values ('manage_pricing_settings','Manage company pricing settings','Pricing',72),('view_opportunities','View opportunities','CRM',42),('manage_opportunities','Manage opportunities','CRM',43),('view_staging','View material staging','Inventory',92),('manage_staging','Manage material staging','Inventory',93) on conflict do nothing;
insert into public.role_permissions(role,permission_key,allowed) select r.role,p.permission_key,case when r.role='owner' then true when p.permission_key='manage_pricing_settings' then false when p.permission_key='view_opportunities' then r.role in ('manager','csr_dispatch','marketing') when p.permission_key='manage_opportunities' then r.role in ('manager','csr_dispatch') when p.permission_key='view_staging' then r.role in ('manager','csr_dispatch','technician','accounting') when p.permission_key='manage_staging' then r.role in ('manager','csr_dispatch') else false end from (values('owner'),('manager'),('csr_dispatch'),('technician'),('marketing'),('accounting')) r(role) cross join public.permission_definitions p where p.permission_key in ('manage_pricing_settings','view_opportunities','manage_opportunities','view_staging','manage_staging') on conflict(role,permission_key) do nothing;